def in_sph_tri(p, a, b, c):
    # robust: p inside triangle abc iff same side of each great-circle edge as opposite vertex
    def s(u,v,q): return np.sign(np.dot(np.cross(u,v), q))
    return (s(a,b,p)==s(a,b,c) and s(b,c,p)==s(b,c,a) and s(c,a,p)==s(c,a,b))

